import { Box, IconButton, type Theme } from '@mui/material';
import ChevronLeft from 'mdi-material-ui/ChevronLeft';
import ChevronRight from 'mdi-material-ui/ChevronRight';
import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';

/** Width of each floating scroll button. */
export const SCROLL_BUTTON_WIDTH = 32;
/** Distance scrolled by one scroll button click. */
export const SCROLL_STEP = 200;
/** Sub-pixel tolerance used when deciding whether the scroll end has been reached. */
const SCROLL_EDGE_TOLERANCE = 1;

interface HorizontalScrollAreaProps {
    children: ReactNode
}

interface ScrollState {
    canScrollEnd: boolean
    canScrollStart: boolean
}

const NO_SCROLL: ScrollState = { canScrollEnd: false, canScrollStart: false };

/** Reads overflow and scroll-direction availability from the scroller and its content. */
function measureScrollState(scroller: HTMLElement, content: HTMLElement): ScrollState {
    if (content.scrollWidth <= scroller.clientWidth) return NO_SCROLL;
    const canScrollStart = scroller.scrollLeft > SCROLL_EDGE_TOLERANCE;
    const canScrollEnd = scroller.scrollLeft + scroller.clientWidth < scroller.scrollWidth - SCROLL_EDGE_TOLERANCE;

    return { canScrollEnd, canScrollStart };
}

function isSameScrollState(left: ScrollState, right: ScrollState) {
    return left.canScrollEnd === right.canScrollEnd && left.canScrollStart === right.canScrollStart;
}

function startFade(theme: Theme) {
    return `linear-gradient(to right, ${theme.palette.background.paper} 60%, transparent)`;
}

function endFade(theme: Theme) {
    return `linear-gradient(to left, ${theme.palette.background.paper} 60%, transparent)`;
}

const buttonContainerSx = {
    alignItems: 'center',
    bottom: 0,
    display: 'flex',
    justifyContent: 'center',
    position: 'absolute',
    top: 0,
    width: SCROLL_BUTTON_WIDTH,
    zIndex: 1,
} as const;
const startButtonContainerSx = { ...buttonContainerSx, background: startFade, left: 0 };
const endButtonContainerSx = { ...buttonContainerSx, background: endFade, right: 0 };
const scrollerSx = {
    display: 'flex',
    gap: 'inherit',
    height: '100%',
    overflowX: 'auto',
    overflowY: 'hidden',
    scrollbarWidth: 'none',
    scrollPaddingInline: `${SCROLL_BUTTON_WIDTH}px`,
    '&::-webkit-scrollbar': { display: 'none' },
} as const;
const contentSx = { alignItems: 'center', display: 'flex', flex: '1 0 auto', gap: 'inherit' };
const rootSx = { flex: 1, gap: 'inherit', minWidth: 0, position: 'relative' };

/** Horizontal scroller without native scrollbars: floating start/end buttons, wheel and focus scrolling. */
export function HorizontalScrollArea(props: HorizontalScrollAreaProps) {
    const { children } = props;
    const scrollerRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const [scrollState, setScrollState] = useState<ScrollState>(NO_SCROLL);

    const updateScrollState = useCallback(() => {
        const scroller = scrollerRef.current;
        const content = contentRef.current;
        if (!scroller || !content) return;
        const nextState = measureScrollState(scroller, content);
        setScrollState(current => isSameScrollState(current, nextState) ? current : nextState);
    }, []);

    useEffect(() => {
        const scroller = scrollerRef.current;
        const content = contentRef.current;
        if (!scroller || !content) return;

        const handleWheel = (event: WheelEvent) => {
            if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
            if (content.scrollWidth <= scroller.clientWidth) return;
            event.preventDefault();
            scroller.scrollLeft += event.deltaY;
        };
        const handleFocusIn = (event: FocusEvent) => {
            if (!(event.target instanceof HTMLElement)) return;
            event.target.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        };
        const resizeObserver = new ResizeObserver(updateScrollState);
        resizeObserver.observe(scroller);
        resizeObserver.observe(content);
        scroller.addEventListener('scroll', updateScrollState);
        scroller.addEventListener('wheel', handleWheel, { passive: false });
        scroller.addEventListener('focusin', handleFocusIn);
        updateScrollState();

        return () => {
            resizeObserver.disconnect();
            scroller.removeEventListener('scroll', updateScrollState);
            scroller.removeEventListener('wheel', handleWheel);
            scroller.removeEventListener('focusin', handleFocusIn);
        };
    }, [updateScrollState]);

    const scrollToStart = useCallback(() => {
        scrollerRef.current?.scrollBy({ behavior: 'smooth', left: -SCROLL_STEP });
    }, []);
    const scrollToEnd = useCallback(() => {
        scrollerRef.current?.scrollBy({ behavior: 'smooth', left: SCROLL_STEP });
    }, []);

    const { canScrollEnd, canScrollStart } = scrollState;

    return (
        <Box sx={rootSx}>
            {canScrollStart ? (
                <Box sx={startButtonContainerSx}>
                    <IconButton aria-label="Scroll left" onClick={scrollToStart} size="small">
                        <ChevronLeft fontSize="small" />
                    </IconButton>
                </Box>
            ) : null}
            <Box ref={scrollerRef} sx={scrollerSx}>
                <Box ref={contentRef} sx={contentSx}>
                    {children}
                </Box>
            </Box>
            {canScrollEnd ? (
                <Box sx={endButtonContainerSx}>
                    <IconButton aria-label="Scroll right" onClick={scrollToEnd} size="small">
                        <ChevronRight fontSize="small" />
                    </IconButton>
                </Box>
            ) : null}
        </Box>
    );
}

import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { HorizontalScrollArea, SCROLL_STEP } from './horizontal_scroll_area';

const SCROLLER_WIDTH = 300;
const OVERFLOWING_CONTENT_WIDTH = 800;
const FITTING_CONTENT_WIDTH = 200;
const WHEEL_DELTA = 120;

interface ScrollLayout {
    contentWidth: number
    scrollLeft: number
}

interface ScrollHarness {
    layout: ScrollLayout
    scrollBy: ReturnType<typeof vi.fn>
    scroller: HTMLElement
}

function renderScrollArea(contentWidth: number, scrollLeft = 0): ScrollHarness {
    render(
        <HorizontalScrollArea>
            <button type="button">First</button>
            <button type="button">Last</button>
        </HorizontalScrollArea>,
    );
    const content = screen.getByRole('button', { name: 'First' }).parentElement;
    const scroller = content?.parentElement;
    if (!content || !scroller) throw new Error('Expected scroll area structure');
    const layout: ScrollLayout = { contentWidth, scrollLeft };
    const scrollBy = vi.fn();
    Object.defineProperties(content, { scrollWidth: { configurable: true, get: () => layout.contentWidth } });
    Object.defineProperties(scroller, {
        clientWidth: { configurable: true, get: () => SCROLLER_WIDTH },
        scrollBy: { configurable: true, value: scrollBy },
        scrollLeft: {
            configurable: true,
            get: () => layout.scrollLeft,
            set: (value: number) => { layout.scrollLeft = value; },
        },
        scrollWidth: { configurable: true, get: () => layout.contentWidth },
    });
    fireEvent.scroll(scroller);

    return { layout, scrollBy, scroller };
}

function scrollEndPosition() {
    return OVERFLOWING_CONTENT_WIDTH - SCROLLER_WIDTH;
}

describe('HorizontalScrollArea', () => {
    afterEach(cleanup);

    it('shows no buttons when content fits', () => {
        renderScrollArea(FITTING_CONTENT_WIDTH);

        expect(screen.queryByRole('button', { name: 'Scroll left' })).not.toBeInTheDocument();
        expect(screen.queryByRole('button', { name: 'Scroll right' })).not.toBeInTheDocument();
    });

    it('shows only the right button at the start', () => {
        renderScrollArea(OVERFLOWING_CONTENT_WIDTH);

        expect(screen.queryByRole('button', { name: 'Scroll left' })).not.toBeInTheDocument();
        expect(screen.getByRole('button', { name: 'Scroll right' })).toBeInTheDocument();
    });

    it('shows both buttons in the middle', () => {
        renderScrollArea(OVERFLOWING_CONTENT_WIDTH, SCROLL_STEP);

        expect(screen.getByRole('button', { name: 'Scroll left' })).toBeInTheDocument();
        expect(screen.getByRole('button', { name: 'Scroll right' })).toBeInTheDocument();
    });

    it('shows only the left button at the end', () => {
        renderScrollArea(OVERFLOWING_CONTENT_WIDTH, scrollEndPosition());

        expect(screen.getByRole('button', { name: 'Scroll left' })).toBeInTheDocument();
        expect(screen.queryByRole('button', { name: 'Scroll right' })).not.toBeInTheDocument();
    });

    it('updates buttons when scrolled', () => {
        const { layout, scroller } = renderScrollArea(OVERFLOWING_CONTENT_WIDTH);

        layout.scrollLeft = scrollEndPosition();
        fireEvent.scroll(scroller);

        expect(screen.getByRole('button', { name: 'Scroll left' })).toBeInTheDocument();
        expect(screen.queryByRole('button', { name: 'Scroll right' })).not.toBeInTheDocument();
    });

    it('scrolls by one step when a button is clicked', () => {
        const { scrollBy } = renderScrollArea(OVERFLOWING_CONTENT_WIDTH, SCROLL_STEP);

        fireEvent.click(screen.getByRole('button', { name: 'Scroll right' }));
        fireEvent.click(screen.getByRole('button', { name: 'Scroll left' }));

        expect(scrollBy).toHaveBeenNthCalledWith(1, { behavior: 'smooth', left: SCROLL_STEP });
        expect(scrollBy).toHaveBeenNthCalledWith(2, { behavior: 'smooth', left: -SCROLL_STEP });
    });

    it('converts vertical wheel movement into horizontal scrolling when content overflows', () => {
        const { layout, scroller } = renderScrollArea(OVERFLOWING_CONTENT_WIDTH);

        const notCancelled = fireEvent.wheel(scroller, { deltaX: 0, deltaY: WHEEL_DELTA });

        expect(notCancelled).toBe(false);
        expect(layout.scrollLeft).toBe(WHEEL_DELTA);
    });

    it('leaves sideways wheel movement alone', () => {
        const { layout, scroller } = renderScrollArea(OVERFLOWING_CONTENT_WIDTH);

        const notCancelled = fireEvent.wheel(scroller, { deltaX: WHEEL_DELTA, deltaY: 0 });

        expect(notCancelled).toBe(true);
